    // ---- terminals ----
    pub async fn get(&mut self) -> Result<Option<CompositeAccountRow>> { let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "one").await?;
        Ok(match rows.take_cells().into_iter().next() {
            Some(mut src) => Some(CompositeAccountRow::from_row(&mut src, &rows.assemble, &rows)?),
            None => None,
        })
    }

    pub async fn gets(&mut self) -> Result<Collection<CompositeAccountRow>> { let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "all").await?;
        collect(&mut rows, self.key_fn.as_deref())
    }

    pub async fn gets_after(&mut self, cursor: &str, per: u32) -> Result<orm::KeysetPage<CompositeAccountRow>> {
        self.q.keyset("after", cursor, per, &["tenant_id", "account_id"])?;
        let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "all").await?;
        let (next_cursor, previous_cursor) = rows.keyset_cursors(&self.q.req.ir.query.order)?;
        let items = collect(&mut rows, self.key_fn.as_deref())?;
        Ok(orm::KeysetPage { items, next_cursor, previous_cursor })
    }

    pub async fn gets_before(&mut self, cursor: &str, per: u32) -> Result<orm::KeysetPage<CompositeAccountRow>> {
        self.q.keyset("before", cursor, per, &["tenant_id", "account_id"])?;
        let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "all").await?;
        rows.reverse_main();
        let (next_cursor, previous_cursor) = rows.keyset_cursors(&self.q.req.ir.query.order)?;
        let items = collect(&mut rows, self.key_fn.as_deref())?;
        Ok(orm::KeysetPage { items, next_cursor, previous_cursor })
    }

    /// Visits independently owned rows without accumulating the complete result.
    pub async fn stream(&mut self, visit: impl FnMut(CompositeAccountRow) -> bool) -> Result<db::StreamResult> {
        let mut visit = visit;
        let binding = self.binding.clone();
        let ex = binding.resolve()?;
        db::stream(ex, &mut self.q.req, |mut src, rows| {
            let row = CompositeAccountRow::from_row(&mut src, &rows.assemble, rows)?;
            Ok(visit(row))
        }).await
    }


