    pub async fn min_account_id(&mut self) -> Result<Option<i64>> { let binding = self.binding.clone(); let ex = binding.resolve()?; self.q.req.ir.agg = "account_id".into(); let mut v = db::scalar(ex, &mut self.q.req, "min").await?; let v = &mut v; Ok(if v.is_null() { None } else { Some(v.as_i64()) }) }
    /// None when no row matches.
    pub async fn max_account_id(&mut self) -> Result<Option<i64>> { let binding = self.binding.clone(); let ex = binding.resolve()?; self.q.req.ir.agg = "account_id".into(); let mut v = db::scalar(ex, &mut self.q.req, "max").await?; let v = &mut v; Ok(if v.is_null() { None } else { Some(v.as_i64()) }) }
    pub async fn count_distinct_name(&mut self) -> Result<i64> { let binding = self.binding.clone(); let ex = binding.resolve()?; self.q.req.ir.agg = "name".into(); Ok(db::scalar(ex, &mut self.q.req, "count_distinct").await?.as_i64()) }
    /// None when no row matches.
    pub async fn min_name(&mut self) -> Result<Option<String>> { let binding = self.binding.clone(); let ex = binding.resolve()?; self.q.req.ir.agg = "name".into(); let mut v = db::scalar(ex, &mut self.q.req, "min").await?; let v = &mut v; Ok(if v.is_null() { None } else { Some(v.take_string()) }) }
